using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;
using OnlineStore.Data;
using OnlineStore.Models;
namespace OnlineStore.Controllers;
public class AdminProductsController(StoreContext db) : Controller { async Task Categories(int? selected=null) => ViewBag.CategoryId=new SelectList(await db.Categories.ToListAsync(),"Id","Name",selected); public async Task<IActionResult> Index()=>View(await db.Products.Include(p=>p.Category).ToListAsync()); public async Task<IActionResult> Details(int id){var p=await db.Products.Include(p=>p.Category).FirstOrDefaultAsync(p=>p.Id==id);return p is null?NotFound():View(p);} public async Task<IActionResult> Create(){await Categories();return View();} [HttpPost] public async Task<IActionResult> Create(Product p){if(!ModelState.IsValid){await Categories(p.CategoryId);return View(p);}db.Products.Add(p);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult> Edit(int id){var p=await db.Products.FindAsync(id);if(p is null)return NotFound();await Categories(p.CategoryId);return View(p);} [HttpPost] public async Task<IActionResult> Edit(Product p){if(!ModelState.IsValid){await Categories(p.CategoryId);return View(p);}db.Update(p);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult> Delete(int id){var p=await db.Products.Include(p=>p.Category).FirstOrDefaultAsync(p=>p.Id==id);return p is null?NotFound():View(p);} [HttpPost,ActionName("Delete")] public async Task<IActionResult> DeleteConfirmed(int id){var p=await db.Products.FindAsync(id);if(p is not null){db.Products.Remove(p);await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));} }
